function replaceTextNodes() {
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node;

  while ((node = walker.nextNode())) {
    if (!node.nodeValue) continue;

    let value = node.nodeValue;
    for (const [from, to] of TEXT_REPLACEMENTS) {
      if (value.includes(from)) value = value.replaceAll(from, to);
    }

    if (value !== node.nodeValue) node.nodeValue = value;
  }
}

function setDefinition(paragraph, title, text) {
  const expected = `${title}: ${text}`;
  if (paragraph.textContent.trim() === expected) return;

  paragraph.replaceChildren();
  const strong = document.createElement("strong");
  strong.textContent = `${title}:`;
  paragraph.append(strong, ` ${text}`);
}

function replaceClarifications() {
  const details = [...document.querySelectorAll("details")].find(
    (element) => element.querySelector("summary")?.textContent.trim() === "توضيحات",
  );
  if (!details) return;

  const paragraphs = details.querySelectorAll(".definition-list > p");
  if (paragraphs.length < 3) return;

  setDefinition(paragraphs[1], OFFICIAL_TITLE, OFFICIAL_TEXT);
  setDefinition(paragraphs[2], INTERACTIVE_TITLE, INTERACTIVE_TEXT);
}

function applyAllChanges() {
  replaceTextNodes();
  replaceClarifications();
}

queueMicrotask(applyAllChanges);
window.requestAnimationFrame(applyAllChanges);
window.addEventListener("load", applyAllChanges);

const observer = new MutationObserver(applyAllChanges);
observer.observe(document.documentElement, {
  childList: true,
  subtree: true,
  characterData: true,
});

let attempts = 0;
const timer = window.setInterval(() => {
  applyAllChanges();
  attempts += 1;
  if (attempts >= 120) window.clearInterval(timer);
}, 250);
